-- Isolated transactional checks. All fixtures roll back, including sessions and images.
begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'Inventory check failed: %',message;end if;end $$;
insert into public.onebite_users(id,name,username,role,active) values ('11111111-1111-4111-8111-111111111111','Catalog test Owner','catalog-test-owner','Owner',true),('22222222-2222-4222-8222-222222222222','Catalog test Cashier','catalog-test-cashier','Cashier',true);
insert into public.onebite_credentials(user_id,pin_hash,must_change) values ('11111111-1111-4111-8111-111111111111','test-only',false),('22222222-2222-4222-8222-222222222222','test-only',false);
insert into public.onebite_sessions(token_hash,user_id,expires_at,mfa_at) values(repeat('1',64),'11111111-1111-4111-8111-111111111111',now()+interval '1 day',now()),(repeat('2',64),'22222222-2222-4222-8222-222222222222',now()+interval '1 day',null);
insert into public.onebite_role_permissions(role,permission) values('Cashier','inventory.access') on conflict do nothing;
select pg_temp.assert(not has_function_privilege('anon','public.onebite_inventory_api(text,jsonb,text)','execute'),'anonymous RPC denied');
select pg_temp.assert(not has_table_privilege('authenticated','public.onebite_catalog','select'),'direct catalog reads denied');
select pg_temp.assert((public.onebite_inventory_api('list','{}',repeat('0',64))->>'error')='unauthorized','invalid session denied');
select pg_temp.assert((public.onebite_inventory_api('list','{}',repeat('2',64))->>'canEdit')='false','staff read only');
select pg_temp.assert((public.onebite_inventory_api('save','{}',repeat('2',64))->>'error')='forbidden','staff cannot author');
select pg_temp.assert((public.onebite_inventory_api('save','{}',repeat('1',64))->>'error')='invalid_item','missing operation rejected');
create temp table payload as select jsonb_build_object('id','33333333-3333-4333-8333-333333333333','fingerprint',repeat('3',64),'item',jsonb_build_object('id','44444444-4444-4444-8444-444444444444','kind','material','name','Catalog test wrapper','nameEn','','category','ingredient','unit','pcs','priceKhr',null,'packName','Pack','packQuantity',100,'description','','active',true,'photoPath',null,'revision',0)) value;
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->'item'->>'revision')='1','Owner creates');
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->'item'->>'revision')='1','retry uses receipt');
select pg_temp.assert((select revision=1 from public.onebite_catalog where id='44444444-4444-4444-8444-444444444444'),'retry causes no second write');
select pg_temp.assert((public.onebite_inventory_api('save',(select jsonb_set(value,'{fingerprint}',to_jsonb(repeat('9',64))) from payload),repeat('1',64))->>'error')='operation_conflict','operation content immutable');
update payload set value=jsonb_set(value,'{id}','"55555555-5555-4555-8555-555555555555"');
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->>'error')='stale_revision','stale edit rejected');
update payload set value=jsonb_set(value,'{item,revision}','1');
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->'item'->>'revision')='2','current edit accepted');
update payload set value=jsonb_set(jsonb_set(jsonb_set(value,'{id}','"66666666-6666-4666-8666-666666666666"'),'{item,revision}','2'),'{item,unit}','"g"');
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->>'error')='immutable_unit','base unit protected');
select pg_temp.assert((public.onebite_inventory_api('photo.read','{"photoPath":"11111111-1111-4111-8111-111111111111/33333333-3333-4333-8333-333333333333.jpg"}',repeat('2',64))->>'error')='not_found','unattached photos unreadable');
delete from public.onebite_role_permissions where role='Cashier' and permission='inventory.access';
select pg_temp.assert((public.onebite_inventory_api('list','{}',repeat('2',64))->>'error')='forbidden','revoked grant takes effect');
update public.onebite_sessions set mfa_at=now()-interval '7 days' where token_hash=repeat('1',64);
select pg_temp.assert((public.onebite_inventory_api('save',(select value from payload),repeat('1',64))->>'error')='reauth_required','Owner writes require recent verification');
rollback;
